use editor_aqua::settings::licences::{Licence, catalogue};

fn notices() -> String {
    let rule = "=".repeat(80);
    let editor = [
        "Rust crates compiled into this program, with the licence texts they ship.",
        "Generated by cargo-about from Cargo.lock.",
        "",
        &rule,
        "MIT License (MIT)",
        "",
        "Used by:",
        "- serde 1.0.228 <https://github.com/serde-rs/serde>",
        "- tokio 1.48.0 <https://github.com/tokio-rs/tokio>",
        "",
        "Copyright (c) the serde and tokio authors",
        "",
        &rule,
        "Apache License 2.0 (Apache-2.0)",
        "",
        "Used by:",
        "- windows-sys 0.52.0",
        "",
        "Apache text for 0.52",
    ]
    .join("\n");
    let forge = [
        "Rust crates compiled into this program, with the licence texts they ship.",
        "",
        &rule,
        "MIT License (MIT)",
        "",
        "Used by:",
        "- serde 1.0.228 <https://github.com/serde-rs/serde>",
        "",
        "Copyright (c) the serde and tokio authors",
        "",
        &rule,
        "Apache License 2.0 (Apache-2.0)",
        "",
        "Used by:",
        "- windows-sys 0.61.2",
        "",
        "Apache text for 0.61",
    ]
    .join("\n");
    [
        ("LICENSE.md", "Artisan licence"),
        (
            "crates/editor-assets/licenses/spline-sans-OFL.txt",
            "SIL Open Font License",
        ),
        (
            "crates/editor-assets/licenses/simple-icons-NOTES.md",
            "Attestation notes",
        ),
        ("notices/editor.txt", editor.as_str()),
        ("notices/forge.txt", forge.as_str()),
    ]
    .map(|(label, text)| format!("==== {label} ====\n\n{text}\n\n"))
    .concat()
}

fn names(licences: &[Licence]) -> Vec<&str> {
    licences
        .iter()
        .map(|licence| licence.name.as_str())
        .collect()
}

#[test]
fn every_bundled_licence_and_crate_gets_its_own_row() {
    let licences = catalogue(&notices());
    assert_eq!(
        names(&licences),
        [
            "Artisan Editor",
            "serde",
            "Spline Sans",
            "tokio",
            "windows-sys 0.52.0",
            "windows-sys 0.61.2",
        ]
    );
    let serde = &licences[1];
    assert_eq!(
        serde.text,
        "MIT License (MIT)\n\nCopyright (c) the serde and tokio authors"
    );
    assert_eq!(licences[2].text, "SIL Open Font License");
    assert_eq!(
        licences[5].text,
        "Apache License 2.0 (Apache-2.0)\n\nApache text for 0.61"
    );
}

#[test]
fn the_about_page_mounts_only_the_licences_in_view() {
    static MANY: std::sync::LazyLock<Vec<Licence>> = std::sync::LazyLock::new(|| {
        (0..400)
            .map(|index| Licence {
                name: format!("crate-{index:03}"),
                text: "MIT".to_owned(),
            })
            .collect()
    });
    use aqua_ui::element::Box as UiBox;
    use editor_aqua::core::{Screen, SettingsPage};
    use editor_aqua::settings::{
        about::BuildInfo, controller::SettingsController, licences::Licences, view,
    };
    use editor_aqua::shell::{host::ShellResources, wheel::keyed_node};
    use editor_aqua::ui::theme::ArtisanTheme;
    let viewport = aqua_core::Size::new(1100.0, 760.0);
    let directory = tempfile::tempdir().unwrap();
    let mut core = test_support::editor::core::test_core(directory.path());
    core.navigate(Screen::Settings(SettingsPage::About));
    let build = BuildInfo {
        licences: Licences::new(|| Ok(MANY.as_slice())),
        ..BuildInfo::default()
    };
    let mut resources = ShellResources::new(1.0).unwrap();
    let app = &mut resources.ui;
    app.set_viewport(viewport.w, viewport.h, 1.0);
    let page = view::build(
        &SettingsController::default(),
        &core,
        &ArtisanTheme::resolved(),
        &build,
        viewport,
        true,
        std::rc::Rc::new(|_| {}),
    );
    app.mount(move |_| {
        UiBox::new()
            .width(viewport.w)
            .height(viewport.h)
            .child(page)
            .build()
    })
    .unwrap();
    app.build_frame().unwrap();
    app.build_frame().unwrap();
    let mounted: Vec<usize> = (0..400)
        .filter(|index| keyed_node(app, &format!("settings-licence-{index}")).is_some())
        .collect();
    assert!(
        mounted.contains(&0) && mounted.len() < 40,
        "only a window of licence rows is mounted: {} rows",
        mounted.len()
    );
}
